If ${\omega}_1 \dots {\omega}_r$ are smooth one-forms on $X$ and $\alpha_1,\dots \alpha_s$ are loops
based at $x_0$ then

\begin{equation}
\left<\int {\omega}_1\dots {\omega}_r,\prod_{i=1}^{s} (\alpha_i-1)
\right>=\begin{cases} \prod_{i=1}^{s} \int_{\alpha_j} {\omega}_j \text
{ if  r=s}\\
0 \text{ if r $<$ s}. \end{cases} \label{period}
\end{equation}

\label{hainproduct}

\label{exact}
Suppose ${\omega}_1,\dots {\omega}_s$ are $1$-forms on $X$ and $\gamma$ is a path on $X$.  If $f$ is a function on $M$ then 
\begin{itemize}

\item $$\int_{\gamma} df  {\omega}_1\dots {\omega}_s=\int_{\gamma} (f{\omega}_1){\omega}_2\dots {\omega}_s - f (\gamma(0))\int_{\gamma} {\omega}_1\dots {\omega}_s.$$

\item $$\int_{\gamma} {\omega}_1\dots {\omega}_{i-1} df  {\omega}_{i}\dots {\omega}_s=\int_{\gamma} {\omega}_1\dots (f{\omega}_{i}){\omega}_{i+1}\dots {\omega}_s$$ 
$$- \int_{\gamma} {\omega}_1\dots (f{\omega}_{i-1}){\omega}_i\dots {\omega}_s$$

\item $$\int_{\gamma} {\omega}_1\dots {\omega}_s df = f(\gamma(1))\int_{\gamma} {\omega}_1\dots {\omega}_s - \int_{\gamma} {\omega}_1\dots {\omega}_{s-1} (f {\omega}_s)$$

\end{itemize}

Let $k>2$ be an even integer and let ${I}$ be an element
of $H^0(B_s({\bar {X}}), x_0)$ and $z_0$ a point on ${\mathfrak  H}$ lying in the fibre over $x_0$.
Then, for every cusp ${\mathbf a}$ and non-negative
integer $m$  we get three twisted Poincar\'{e} series. All of these
are weight $k$, order $s+1$ modular forms and when $m>0$ they are
cusp forms.

\begin{itemize}

\item $\displaystyle{P^1_{m,{\mathbf a}}(z,{I})=\sum_{\gamma \in \Gamma_{{\mathbf a}}\backslash
\Gamma} \left ( \int_{z_0}^{z} {I} \right
)\frac{e(m\sigma_{{\mathbf a}}^{-1}\gamma
z)}{j(\sigma_{{\mathbf a}}^{-1}\gamma,z)^k}}$

\item $\displaystyle {P^2_{m,{\mathbf a}}(z,{I})=\sum_{\gamma \in \Gamma_{{\mathbf a}}\backslash
\Gamma}\left ( \int_{z_0}^{\gamma z_0} {I} \right )
\frac{e(m\sigma_{{\mathbf a}}^{-1} \gamma
z)}{j(\sigma_{{\mathbf a}}^{-1}\gamma,z)^k}}$

\item $\displaystyle{P^3_{m,{\mathbf a}}(z,{I})=\sum_{\gamma \in \Gamma_{{\mathbf a}}\backslash
\Gamma}\left ( \int_{z}^{\gamma z} {I} \right )
\frac{e(m\sigma_{{\mathbf a}}^{-1}\gamma
z)}{j(\sigma_{{\mathbf a}}^{-1}\gamma,z)^k}}$

\end{itemize}

Further, there are relations between these modular forms coming from
the fact that the integral  of ${I}$ over the path $\{z_0,\gamma z_0\}$ can be expressed, using Proposition \ref{alphabeta}, as a sum of products of integrals over  $\{z_0,z\}$,
$\{z,\gamma z\}$  and $\{\gamma z,\gamma z_0\}$, where $\{z_0,z_1\}$ denotes a path from $z_0$ to $z_1$ in ${\mathfrak  H}$. 
\[
\xy
(0,0)*{}; (0,20)*{}**\dir{-}
?(.5)*\dir{>};
(0,20)*{};(20,20)*{}**\dir{-}
?(.5)*\dir{>};
(20,20)*{};(20,0)*{}**\dir{-}
?(.5)*\dir{>};
(20,0)*{};(0,0)*{}**\dir{-}
?(.5)*\dir{<};
(20,-2)*{\gamma z_0};
(0,-2)*{z_0};
(0,22)*{z};
(20,22)*{\gamma z};



\endxy
\]

For $i=1$, the series $P^1$ is simply a product of the classical
Poincar\'{e} series and $\int_{z_0}^{z} {I}$, both of which converge
for $k>2$.  

For $P^3(z,{I})$ the argument is similar to the case of ${I}=f$ in
\cite{dios}.  We can assume $I$ is in $H^0(\bar{B}_s({\bar {X}}),x_0)$ since an element of $H^0(B_s({\bar {X}}),x_0)$ differs from such an $I$ by a constant, and in the twisted Poincar\'{e} series this amounts to adding a constant multiple of a classical Poincar\'{e} series. 

We use the estimate \cite{DKMO}, Lemma 3 -- for a
classical cusp form $f$  of weight $2$, any cusp ${\mathbf a}$,

$$\int_{z_0}^{z} f(w)dw \ll |\log (Im(\sigma_{{\mathbf a}} z))|+1.$$

To simplify exposition, we use the notation $y_{{\mathbf a}}(z)$ for
$Im(\sigma_{{\mathbf a}}(z))$. Using the above estimate repeatedly, we have
that for an iterated integral ${I}$ of length $r$,
\begin{equation}
\int_{z_0}^{z} {I} \ll \frac{|\log^{r}(y_{{\mathbf a}}(
z))|}{r!}+\frac{|\log^{r-1} (y_{{\mathbf a}}(z))|}{(r-1)!} \dots +1
\label{est1}
\end{equation}

Observe that
\begin{equation}
\frac{|\log^{r}(y_{{\mathbf a}}( z))|}{r!}+\frac{|\log^{r-1}(
y_{{\mathbf a}}(z))|}{(r-1)!} \dots +1 < exp(|\log( y_{{\mathbf a}} (z))|) < y_{{\mathbf a}}
(z)+y_{{\mathbf a}} (z)^{-1} \label{est2}
\end{equation}

as $exp(|\log(x)|)=x$ or $x^{-1}$. Replacing $y_{{\mathbf a}} (z)$ by
$y_{{\mathbf a}}( z)^{\epsilon}$, we have, for $0<\epsilon<1$, using that
$\epsilon^{r}<\epsilon$,

\begin{equation}
\int_{z_0}^{z} {I} \ll \epsilon^{-r} y_{{\mathbf a}} (z)^{\epsilon}+y_{{\mathbf a}}
(z)^{-\epsilon}) \label{est3}
\end{equation}

To apply this to the convergence of the twisted Poincar\'{e} series
we need an estimate for $\int_{z}^{\gamma z} {I}$. We have
\begin{equation}
\int_z^{\gamma z} {I} = \sum_{j=0}^{r} \int_z^{z_0}
{I}_{j}\int_{z_0}^{\gamma z} {I}'_{j} \label{exp1}
\end{equation}

where ${I}_j$ and ${I}'_j$ are iterated integrals of lengths $j$ and
$r-j$ respectively. From \eqref{est3} and \eqref{exp1} we have

\begin{equation}
|\int_z^{\gamma z} {I}| \ll
\epsilon^{-r}(r+1)(y_{{\mathbf a}}(z)^{\epsilon}+y_{{\mathbf a}}(z)^{-\epsilon})(y_{{\mathbf a}}(\gamma
z)^{\epsilon}+y_{{\mathbf a}}(\gamma z)^{-\epsilon}) \label{est4}
\end{equation}

So we have

$$P^3_{{\mathbf a}}(z,{I}) \ll \sum_{\gamma \in \Gamma_{{\mathbf a}}\backslash \Gamma}\frac{(y_{{\mathbf a}}(z)^{\epsilon}+y_{{\mathbf a}}(z)^{-\epsilon})(y_{{\mathbf a}}(\gamma
z)^{\epsilon}+y_{{\mathbf a}}(\gamma z)^{-\epsilon})}{j(\gamma,z)^{-k}}$$

We have $y_{{\mathbf a}}(\gamma z)=\frac{y_{{\mathbf a}}(z)}{j(\gamma,z)^{2}}$.
Replacing $j(\gamma,z)^{-k}$ by $\left (\frac{y_{{\mathbf a}}(\gamma
z)}{y_{{\mathbf a}}(z)}\right )^{k/2}$ in the expression above we get,
$$P^{3}_{{\mathbf a}}(z,{I}) \ll y_{{\mathbf a}}(z)^{\epsilon-k/2}\left ( \sum_{ \gamma \in \Gamma_{{\mathbf a}} \backslash \Gamma}
 y_{{\mathbf a}}(\gamma z)^{k/2+\epsilon} + \sum_{ \gamma \in \Gamma_{{\mathbf a}} \backslash \Gamma} y_{{\mathbf a}}(\gamma z)^{k/2-\epsilon} \right )
+ $$
$$ +  y_{{\mathbf a}}(z)^{-\epsilon-k/2}\left ( \sum_{\gamma \in \Gamma_{{\mathbf a}}
\backslash \Gamma}
 y_{{\mathbf a}}(\gamma z)^{k/2+\epsilon} + \sum_{ \gamma \in \Gamma_{{\mathbf a}} \backslash \Gamma} y_{{\mathbf a}}(\gamma
 z)^{k/2-\epsilon} \right )$$

The sum

$$E_{{\mathbf a}}(z,s)=\sum_{\gamma \in \Gamma_{{\mathbf a}}
\backslash \Gamma}
 y_{{\mathbf a}}(\gamma z)^{s}$$

is the classical non-holomorphic Eisenstein series for the cusp
${\mathbf a}$ and is known to be absolutely convergent in the region
$Re(s)>1$. So as long as $k/2-\epsilon >1$, that is, $k>2$,  our
series will converge.

Using the change of basepoint formula,  $P^2(z,{I})$ can be
expressed as a finite linear combination terms of the form
$P^1(z,{I}') P^3(z,{I}'')$ for some iterated integrals ${I}'$ and
${I}''$, so converges in the same region.
